#!/usr/bin/env node
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';

const [databasePath, deliveryKey, requestJson, ackMode] = process.argv.slice(2);
assert.ok(databasePath && deliveryKey && requestJson);
assert.ok(['return', 'lose-after-commit'].includes(ackMode));
const request = JSON.parse(requestJson);
const db = new DatabaseSync(databasePath);
try {
  db.exec(`
    CREATE TABLE IF NOT EXISTS deliveries (
      receipt_id TEXT PRIMARY KEY,
      delivery_key TEXT NOT NULL UNIQUE,
      request_id TEXT NOT NULL,
      job_id TEXT NOT NULL,
      recipient_id TEXT NOT NULL,
      stage_ref TEXT NOT NULL,
      report_ref TEXT NOT NULL,
      cell_key TEXT NOT NULL,
      value_sha256 TEXT NOT NULL,
      writer_pid INTEGER NOT NULL
    );
  `);
  const existing = db.prepare('SELECT * FROM deliveries WHERE delivery_key = ?').get(deliveryKey);
  const fields = [
    'request_id',
    'job_id',
    'recipient_id',
    'stage_ref',
    'report_ref',
    'cell_key',
    'value_sha256',
  ];
  if (existing) {
    assert.ok(fields.every((field) => existing[field] === request[field]));
  } else {
    const receipt = `recipient-rcpt-${crypto.createHash('sha256').update(deliveryKey).digest('hex').slice(0, 20)}`;
    db.prepare('INSERT INTO deliveries VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)').run(
      receipt,
      deliveryKey,
      ...fields.map((field) => request[field]),
      process.pid,
    );
  }
  const delivered = db.prepare('SELECT * FROM deliveries WHERE delivery_key = ?').get(deliveryKey);
  if (ackMode === 'lose-after-commit') {
    process.exitCode = 75;
  } else {
    process.stdout.write(`${JSON.stringify({ receipt_id: delivered.receipt_id })}\n`);
  }
} finally {
  db.close();
}
#!/usr/bin/env node
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { DatabaseSync } from 'node:sqlite';

const digest = (value) => crypto.createHash('sha256').update(value).digest('hex');
const { release } = await import('./release-worker.mjs');
assert.equal(typeof release, 'function');

function sample(kind) {
  const base = {
    job_id: 'sample-approved-job',
    recipient_id: 'sample-customer-recipient',
    stage_ref: 'sample-source-stage',
    report_ref: 'sample-source-report',
    cell_key: '0|ssn',
    value_sha256: digest('sample-cell-A'),
  };
  return {
    policy: { ...base, max_distinct_cells: 1 },
    requests: [
      { ...base, request_id: 'sample-request-A' },
      {
        ...base,
        request_id: 'sample-request-B',
        ...(kind === 'distinct'
          ? { cell_key: '1|ssn', value_sha256: digest('sample-cell-B') }
          : {}),
      },
    ],
  };
}

function send(sinkPath, key, request, loseAck) {
  const output = execFileSync(
    process.execPath,
    [
      path.join(import.meta.dirname, 'sink-process.mjs'),
      sinkPath,
      key,
      JSON.stringify(request),
      loseAck ? 'lose-after-commit' : 'return',
    ],
    { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] },
  );
  return JSON.parse(output);
}

function recipientRows(sinkPath, policy) {
  return JSON.parse(
    execFileSync(
      process.execPath,
      [
        path.join(import.meta.dirname, 'lookup-process.mjs'),
        sinkPath,
        'recipient',
        policy.job_id,
        policy.recipient_id,
      ],
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] },
    ),
  );
}

function proxyDb(db, remoteSink) {
  return new Proxy(db, {
    get(target, property) {
      if (property === 'remoteSink') {
        return remoteSink;
      }
      if (property === 'prepare') {
        return (sql) => {
          const statement = target.prepare(sql);
          if (!/\bINSERT\s+INTO\s+sink\b/i.test(sql)) {
            return statement;
          }
          return {
            run(...args) {
              const key = args[0];
              const request =
                args.length === 2
                  ? target.prepare('SELECT * FROM requests WHERE request_id = ?').get(args[1])
                  : Object.fromEntries(
                      [
                        'request_id',
                        'job_id',
                        'recipient_id',
                        'stage_ref',
                        'report_ref',
                        'cell_key',
                        'value_sha256',
                      ].map((field, index) => [field, args[index + 1]]),
                    );
              remoteSink.send(key, request);
              return statement.run(...args);
            },
          };
        };
      }
      const value = target[property];
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });
}

async function runSample(kind) {
  const directory = fs.mkdtempSync(path.join(import.meta.dirname, '.public-check-'));
  const admissionPath = path.join(directory, 'admission.sqlite');
  const sinkPath = path.join(directory, 'recipient.sqlite');
  const observation = sample(kind);
  const [a, b] = observation.requests;
  try {
    const db = new DatabaseSync(admissionPath);
    db.exec(`
      CREATE TABLE policy (job_id TEXT PRIMARY KEY, recipient_id TEXT NOT NULL, max_distinct_cells INTEGER NOT NULL);
      CREATE TABLE requests (
        request_id TEXT PRIMARY KEY, job_id TEXT NOT NULL, recipient_id TEXT NOT NULL,
        stage_ref TEXT NOT NULL, report_ref TEXT NOT NULL, cell_key TEXT NOT NULL,
        value_sha256 TEXT NOT NULL, status TEXT NOT NULL, receipt_id TEXT
      );
      CREATE TABLE sink (
        receipt_id TEXT PRIMARY KEY, request_id TEXT NOT NULL, job_id TEXT NOT NULL,
        recipient_id TEXT NOT NULL, stage_ref TEXT NOT NULL, report_ref TEXT NOT NULL,
        cell_key TEXT NOT NULL, value_sha256 TEXT NOT NULL
      );
    `);
    db.prepare('INSERT INTO policy VALUES (?, ?, ?)').run(a.job_id, a.recipient_id, 1);
    const add = db.prepare('INSERT INTO requests VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)');
    const insert = (request) =>
      add.run(
        request.request_id,
        request.job_id,
        request.recipient_id,
        request.stage_ref,
        request.report_ref,
        request.cell_key,
        request.value_sha256,
        'queued',
        null,
      );
    insert(a);
    const sink = new DatabaseSync(sinkPath);
    sink.exec(`CREATE TABLE deliveries (
      receipt_id TEXT PRIMARY KEY, delivery_key TEXT NOT NULL UNIQUE,
      request_id TEXT NOT NULL, job_id TEXT NOT NULL, recipient_id TEXT NOT NULL,
      stage_ref TEXT NOT NULL, report_ref TEXT NOT NULL, cell_key TEXT NOT NULL,
      value_sha256 TEXT NOT NULL, writer_pid INTEGER NOT NULL
    )`);
    sink.close();
    let loseNextAck = true;
    const remoteSink = {
      send(key, request) {
        const lose = loseNextAck;
        loseNextAck = false;
        return send(sinkPath, key, request, lose);
      },
      lookupRecipient(jobId, recipientId) {
        assert.equal(jobId, a.job_id);
        assert.equal(recipientId, a.recipient_id);
        return recipientRows(sinkPath, observation.policy);
      },
    };
    const proxy = proxyDb(db, remoteSink);
    try {
      await release(proxy, a.request_id);
    } catch (error) {
      if (error.status !== 75) {
        throw error;
      }
    }
    insert(b);
    await release(proxy, b.request_id);
    await release(proxy, a.request_id);
    const statuses = db
      .prepare('SELECT request_id, status, receipt_id FROM requests ORDER BY rowid')
      .all();
    db.close();
    const deliveries = recipientRows(sinkPath, observation.policy);
    const distinct = new Set(
      deliveries.map((receipt) => `${receipt.report_ref}|${receipt.cell_key}`),
    ).size;
    const success =
      deliveries.length === 1 &&
      distinct === 1 &&
      statuses[0].status === 'completed' &&
      (kind === 'overlap'
        ? statuses[1].status === 'completed' && statuses[0].receipt_id === statuses[1].receipt_id
        : statuses[1].status === 'deferred' && statuses[1].receipt_id === null);
    return {
      kind,
      recipient_copies: deliveries.length,
      distinct_cells: distinct,
      request_statuses: statuses.map((item) => item.status),
      valid: success,
    };
  } finally {
    fs.rmSync(directory, { recursive: true, force: true });
  }
}

const samples = [await runSample('overlap'), await runSample('distinct')];
process.stdout.write(`${JSON.stringify({ schema_version: 'f10-v38-public-check-v1', samples })}\n`);
assert.ok(
  samples.every((sample) => sample.valid),
  'release worker failed public recipient outcomes',
);

import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';

const receiptId = (requestId) =>
  `budget-rcpt-${crypto.createHash('sha256').update(requestId).digest('hex').slice(0, 18)}`;

export function openStore(filename) {
  const db = new DatabaseSync(filename);
  db.exec('PRAGMA busy_timeout = 1000');
  return db;
}

export function initializeStore(db, observation) {
  db.exec(`
    CREATE TABLE policy (job_id TEXT PRIMARY KEY, recipient_id TEXT NOT NULL, max_distinct_cells INTEGER NOT NULL);
    CREATE TABLE requests (
      request_id TEXT PRIMARY KEY, job_id TEXT NOT NULL, recipient_id TEXT NOT NULL,
      stage_ref TEXT NOT NULL, report_ref TEXT NOT NULL, cell_key TEXT NOT NULL,
      value_sha256 TEXT NOT NULL, status TEXT NOT NULL, receipt_id TEXT
    );
    CREATE TABLE sink (
      receipt_id TEXT PRIMARY KEY, request_id TEXT NOT NULL, job_id TEXT NOT NULL,
      recipient_id TEXT NOT NULL, stage_ref TEXT NOT NULL, report_ref TEXT NOT NULL,
      cell_key TEXT NOT NULL, value_sha256 TEXT NOT NULL
    );
  `);
  const policy = observation.policy;
  db.prepare('INSERT INTO policy VALUES (?, ?, ?)').run(
    policy.job_id,
    policy.recipient_id,
    policy.max_distinct_protected_cells,
  );
  const insert = db.prepare('INSERT INTO requests VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)');
  for (const request of observation.requests) {
    insert.run(
      request.request_id,
      request.job_id,
      request.recipient_id,
      request.stage_ref,
      request.report_ref,
      request.cell_key,
      request.value_sha256,
      'queued',
      null,
    );
  }
}

function requestById(db, requestId) {
  const request = db.prepare('SELECT * FROM requests WHERE request_id = ?').get(requestId);
  assert.ok(request, `unknown request ${requestId}`);
  return request;
}

// Deliberately flawed authored worker: eligibility is read separately from delivery, and it
// counts requests rather than the distinct delivered-cell union. Its result is stale on commit.
export function brokenPrecheck(db, requestId) {
  const request = requestById(db, requestId);
  const policy = db.prepare('SELECT * FROM policy WHERE job_id = ?').get(request.job_id);
  assert.equal(request.recipient_id, policy.recipient_id);
  const delivered = db
    .prepare('SELECT COUNT(*) AS n FROM sink WHERE job_id = ?')
    .get(request.job_id).n;
  return {
    request_id: requestId,
    allowed: delivered + 1 <= policy.max_distinct_cells,
    delivered_seen: delivered,
  };
}

export function brokenDeliver(db, check) {
  const request = requestById(db, check.request_id);
  return finishRequest(db, request, check.allowed);
}

function finishRequest(db, request, allowed, existingReceipt) {
  assert.equal(request.status, 'queued');
  if (!allowed) {
    db.prepare('UPDATE requests SET status = ? WHERE request_id = ?').run(
      'deferred',
      request.request_id,
    );
    return { status: 'deferred', request_id: request.request_id };
  }
  const receipt = existingReceipt ?? receiptId(request.request_id);
  if (existingReceipt === undefined) {
    db.prepare('INSERT INTO sink VALUES (?, ?, ?, ?, ?, ?, ?, ?)').run(
      receipt,
      request.request_id,
      request.job_id,
      request.recipient_id,
      request.stage_ref,
      request.report_ref,
      request.cell_key,
      request.value_sha256,
    );
  }
  db.prepare('UPDATE requests SET status = ?, receipt_id = ? WHERE request_id = ?').run(
    'completed',
    receipt,
    request.request_id,
  );
  return { status: 'completed', request_id: request.request_id, receipt_id: receipt };
}

export function inspectStore(db) {
  const sink = db.prepare('SELECT * FROM sink ORDER BY rowid').all();
  const requestStatuses = db
    .prepare('SELECT request_id, status, receipt_id FROM requests ORDER BY rowid')
    .all();
  const distinct = new Set(
    sink.map((receipt) => `${receipt.job_id}|${receipt.recipient_id}|${receipt.cell_key}`),
  );
  const max = db.prepare('SELECT max_distinct_cells FROM policy').get().max_distinct_cells;
  return {
    sink,
    request_statuses: requestStatuses,
    distinct_sink_cells: distinct.size,
    over_budget: distinct.size > max,
    duplicate_sink_cells: distinct.size !== sink.length,
  };
}

function releaseLocked(db, requestId) {
  const request = requestById(db, requestId);
  if (request.status === 'completed') {
    return { status: 'completed', request_id: requestId, receipt_id: request.receipt_id };
  }
  if (request.status === 'deferred') {
    return { status: 'deferred', request_id: requestId };
  }

  const policy = db.prepare('SELECT * FROM policy WHERE job_id = ?').get(request.job_id);
  assert.equal(request.recipient_id, policy.recipient_id);
  const existing = db.prepare(`
    SELECT receipt_id, stage_ref, report_ref, value_sha256 FROM sink
    WHERE job_id = ? AND recipient_id = ? AND cell_key = ?
  `).get(request.job_id, request.recipient_id, request.cell_key);
  if (existing) {
    const matches = existing.stage_ref === request.stage_ref &&
      existing.report_ref === request.report_ref && existing.value_sha256 === request.value_sha256;
    return finishRequest(db, request, matches, existing.receipt_id);
  }

  const delivered = db.prepare(`
    SELECT COUNT(DISTINCT cell_key) AS n FROM sink WHERE job_id = ? AND recipient_id = ?
  `).get(request.job_id, request.recipient_id);
  return finishRequest(db, request, delivered.n < policy.max_distinct_cells);
}

export async function release(db, requestId) {
  for (;;) {
    try {
      db.exec('BEGIN IMMEDIATE');
      try {
        const result = releaseLocked(db, requestId);
        db.exec('COMMIT');
        return result;
      } catch (error) {
        db.exec('ROLLBACK');
        throw error;
      }
    } catch (error) {
      // Extended SQLite result codes retain SQLITE_BUSY in the low byte.
      if ((error.errcode & 0xff) !== 5) throw error;
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
  }
}
#!/usr/bin/env node
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { DatabaseSync } from 'node:sqlite';

const [phase, databasePath, firstId, secondId] = process.argv.slice(2);
assert.ok(['first', 'resume'].includes(phase));
assert.ok(databasePath && firstId && secondId);
let messageId = 0;
let incoming = '';

function readLine() {
  const buffer = Buffer.allocUnsafe(4096);
  while (!incoming.includes('\n')) {
    const count = fs.readSync(0, buffer, 0, buffer.length, null);
    if (count === 0) {
      throw new Error('broker-closed');
    }
    incoming += buffer.toString('utf8', 0, count);
  }
  const end = incoming.indexOf('\n');
  const line = incoming.slice(0, end);
  incoming = incoming.slice(end + 1);
  return line;
}

function requestBroker(operation, args) {
  const id = ++messageId;
  fs.writeSync(1, `${JSON.stringify({ rpc: 'f10-v38', id, operation, args })}\n`);
  const response = JSON.parse(readLine());
  assert.equal(response.rpc_response, id);
  if (!response.ok) {
    const error = new Error(response.error?.message ?? 'recipient-service-error');
    error.code = response.error?.code;
    throw error;
  }
  return response.value;
}

const remoteSink = {
  send(deliveryKey, request) {
    return requestBroker('send', { deliveryKey, request });
  },
  lookupRecipient(jobId, recipientId) {
    return requestBroker('lookupRecipient', { jobId, recipientId });
  },
};

function workerDb(db) {
  return new Proxy(db, {
    get(target, property) {
      if (property === 'remoteSink') {
        return remoteSink;
      }
      if (property === 'prepare') {
        return (sql) => {
          const statement = target.prepare(sql);
          if (!/\bINSERT\s+INTO\s+sink\b/i.test(sql)) {
            return statement;
          }
          return {
            run(...args) {
              const deliveryKey = args[0];
              const request =
                args.length === 2
                  ? target.prepare('SELECT * FROM requests WHERE request_id = ?').get(args[1])
                  : Object.fromEntries(
                      [
                        'request_id',
                        'job_id',
                        'recipient_id',
                        'stage_ref',
                        'report_ref',
                        'cell_key',
                        'value_sha256',
                      ].map((field, index) => [field, args[index + 1]]),
                    );
              assert.ok(request);
              remoteSink.send(deliveryKey, request);
              return statement.run(...args);
            },
          };
        };
      }
      const value = target[property];
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });
}

const { release } = await import('./release-worker.mjs');
assert.equal(typeof release, 'function');
const db = new DatabaseSync(databasePath);
try {
  const proxy = workerDb(db);
  if (phase === 'first') {
    try {
      await release(proxy, firstId);
    } catch (error) {
      if (error.code !== 'ACK_LOST') {
        throw error;
      }
    }
  } else {
    await release(proxy, secondId);
    await release(proxy, firstId);
  }
  fs.writeSync(1, `${JSON.stringify({ phase_complete: phase })}\n`);
} finally {
  db.close();
}

